{"path": "/tmp/sv-90f8d02b1f304edc95fe425d787587eb/RecipeShare/Services/RecipeService.cs", "file_text": "using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F.\n2. Roll out dough into a 12-inch circle.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute on top.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                TotalStars = 14, RatingCount = 3 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp the guanciale in a pan.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino.",
                TotalStars = 9, RatingCount = 2 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger",
                Steps = "1. Marinate chicken in yogurt and spices for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté garlic and ginger, add tomato sauce.\n4. Stir in garam masala and cream.\n5. Add chicken pieces and simmer 15 minutes.\n6. Serve over basmati rice.",
                TotalStars = 5, RatingCount = 1 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar\nChili flakes",
                Steps = "1. Soak rice noodles in warm water 20 minutes.\n2. Press and cube tofu, pan-fry until golden.\n3. Mix tamarind paste, fish sauce, sugar, and chili.\n4. Stir-fry noodles with sauce until coated.\n5. Add tofu and bean sprouts.\n6. Garnish with peanuts, green onions, and lime.",
                TotalStars = 8, RatingCount = 2 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nCumin\nChili powder\nGarlic powder",
                Steps = "1. Brown ground beef with cumin, chili powder, and garlic.\n2. Warm taco shells in the oven.\n3. Dice lettuce, tomato, and shred cheese.\n4. Fill shells with seasoned beef.\n5. Top with lettuce, tomato, cheese, and sour cream.",
                TotalStars = 12, RatingCount = 3 },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
                Steps = "1. Halve and pit avocados, scoop into bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, tomato, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
                TotalStars = 4, RatingCount = 1 },
            new() { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
                Steps = "1. Preheat oven to 425°F and grease ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold in chocolate mixture, then flour and vanilla.\n5. Pour into ramekins and bake 12-14 minutes.\n6. Invert onto plates and serve immediately.",
                TotalStars = 10, RatingCount = 2 },
            new() { Id = 8, Title = "Miso Soup", Category = "Asian",
                Ingredients = "Dashi stock\nWhite miso paste\nSilken tofu\nWakame seaweed\nGreen onions",
                Steps = "1. Heat dashi stock until simmering.\n2. Dissolve miso paste into the stock.\n3. Add cubed tofu and rehydrated wakame.\n4. Simmer gently for 2 minutes (do not boil).\n5. Serve topped with sliced green onions.",
                TotalStars = 7, RatingCount = 2 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalStars += stars;
            recipe.RatingCount++;
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}
"}

