arguments.file_text:
@page "/"

<PageTitle>RecipeShare — Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>

<div class="row mt-3">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-3 mb-3">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@CategoryIcon(category) @category</h5>
                    <p class="text-muted">@RecipeService.GetByCategory(category).Count recipe(s)</p>
                    <a href="@($"category/{category}")" class="btn btn-primary btn-sm">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private static string CategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (Recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>@RenderStars(recipe.AverageRating) (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<RecipeShare.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        @if (Recipe is not null)
        {
            <li class="breadcrumb-item"><a href="@($"category/{Recipe.Category}")">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        }
    </ol>
</nav>

@if (Recipe is null)
{
    <p class="text-danger">Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="text-muted">Category: @Recipe.Category</p>

    <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />

    <h3 class="mt-4">Ingredients</h3>
    <ul class="list-group list-group-flush mb-3">
        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = System.Text.RegularExpressions.Regex.Replace(step, @"^\d+\.\s*", "");
            <li class="list-group-item">@text</li>
        }
    </ol>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@using RecipeShare.Services

<div class="my-3">
    <span class="me-2"><strong>Rate this recipe:</strong></span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                style="color: @(star <= HoverStar ? "gold" : "#ccc"); cursor: pointer;"
                @onmouseover="() => HoverStar = star"
                @onmouseout="() => HoverStar = 0"
                @onclick="() => SubmitRating(star)"
                disabled="@Submitted"
                aria-label="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            ★
        </button>
    }
    @if (Submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int HoverStar { get; set; }
    private bool Submitted { get; set; }

    private void SubmitRating(int stars)
    {
        if (Submitted) return;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

