+        <button class="btn btn-link p-0 fs-4 text-decoration-none"
+                style="color: @(star <= HoverStar ? "gold" : "#ccc"); cursor: pointer;"
+                @onmouseover="() => HoverStar = star"
+                @onmouseout="() => HoverStar = 0"
+                @onclick="() => SubmitRating(star)"
+                disabled="@Submitted"
+                aria-label="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
+            ★
+        </button>
+    }
+    @if (Submitted)
+    {
+        <span class="ms-2 text-success">Thanks for rating!</span>
+    }
+</div>
+
+@code {
+    [Parameter, EditorRequired]
+    public int RecipeId { get; set; }
+
+    [Inject] public RecipeService RecipeService { get; set; } = default!;
+
+    private int HoverStar { get; set; }
+    private bool Submitted { get; set; }
+
+    private void SubmitRating(int stars)
+    {
+        if (Submitted) return;
+        RecipeService.AddRating(RecipeId, stars);
+        Submitted = true;
+    }
+}
+

toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer

@using System.ComponentModel.DataAnnotations
@using RecipeShare.Services

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (SubmittedRecipeId is not null)
{
    <div class="alert alert-success">
        Recipe submitted successfully!
        <a href="@($"recipe/{SubmittedRecipeId}")">View your recipe</a>.
    </div>
}

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Title</label>
        <InputText id="title" class="form-control" @bind-Value="Model.Title" />
        <ValidationMessage For="() => Model.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="Model.Category">
            <option value="">— Select a category —</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Asian">Asian</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => Model.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Model.Ingredients" />
        <ValidationMessage For="() => Model.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="Model.Steps" />
        <ValidationMessage For="() => Model.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel Model { get; set; } = new();
    private int? SubmittedRecipeId { get; set; }

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(Model.Title, Model.Category, Model.Ingredients, Model.Steps);
        SubmittedRecipeId = recipe.Id;
        Model = new();
    }

    private sealed class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100)]
        public string Title { get; set; } = "";

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = "";
    }
}

